CREATE TABLE IF NOT EXISTS schema_migrations(id VARCHAR(100) PRIMARY KEY,executed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS destinations(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,slug VARCHAR(170) NOT NULL UNIQUE,image TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,destination_id BIGINT UNSIGNED NOT NULL,name VARCHAR(120) NOT NULL,slug VARCHAR(140) NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_category_destination_slug(destination_id,slug),CONSTRAINT fk_categories_destination FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS places(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,destination_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,slug VARCHAR(200) NOT NULL,description TEXT NOT NULL,phone VARCHAR(60) NULL,address VARCHAR(255) NULL,image TEXT NOT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_places_destination(destination_id),KEY idx_places_category(category_id),CONSTRAINT fk_places_destination FOREIGN KEY(destination_id) REFERENCES destinations(id) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT fk_places_category FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE IF NOT EXISTS place_images(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,place_id BIGINT UNSIGNED NOT NULL,image_url TEXT NOT NULL,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_place_images_place FOREIGN KEY(place_id) REFERENCES places(id) ON DELETE CASCADE ON UPDATE CASCADE);
